<?php require __DIR__.'/includes/header.php';requireAdmin();$rows=db()->query('SELECT a.*,u.name FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 200')->fetchAll();?><h1><?=t('activity')?></h1><section class="card table-wrap"><table><thead><tr><th>User</th><th>Action</th><th>Entity</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['action'])?></td><td><?=e($r['entity'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></section><?php require __DIR__.'/includes/footer.php';?>
